374	// validateLoaded 对解码后的状态做基本不变量检查，违背即视为损坏。
375	func validateLoaded(fd *fileData) error {
376		switch {
377		case fd.Version != int(fileVersion):
378			return fmt.Errorf("%w: version %d in payload", ErrUnsupportedVersion, fd.Version)
379		case len(fd.Trajectory) == 0:
380			return fmt.Errorf("%w: empty trajectory", ErrCorrupt)
381		}
382		if err := validateConfig(fd.Config); err != nil {
383			// 配置不合法不可能由本版本写出。
384			return fmt.Errorf("%w: %v", ErrCorrupt, err)
385		}
386		// 保存的整条轨迹必须满足与导入时相同的时间规则：从初始位姿起
387		// 时间严格递增，且相邻位姿的真实间隔不超过 MaxInterval（恰好
388		// 等于上限合法）。任何一处相等、倒退或超限都使按时间查询失去
389		// 可靠的先后依据，整份文件按损坏拒绝。间隔按真实差值判断：前
390		// 一时间接近 math.MinInt64 而后一时间为非负时，有符号减法会
391		// 溢出回绕成负数，把超限的巨大缺口放过去；此处已保证递增，真
392		// 实差值落在 [1, 2^64-1]，用无符号减法取精确的数学差值再与上
393		// 限比较（MaxInterval 已校验为正）。
394		for i := 1; i < len(fd.Trajectory); i++ {
395			prev, cur := fd.Trajectory[i-1].Time, fd.Trajectory[i].Time
396			if cur <= prev {
397				return fmt.Errorf("%w: trajectory time at pose %d is not strictly increasing", ErrCorrupt, i)
398			}
399			if uint64(cur)-uint64(prev) > uint64(fd.Config.MaxInterval) {
400				return fmt.Errorf("%w: trajectory interval between poses %d and %d exceeds max interval", ErrCorrupt, i-1, i)
401			}
402		}
403		// 新格式的逐帧依据必须与轨迹（除初始位姿外）一一对应；旧文件缺省
404		// 该字段（解码为 nil），数量为 0。
405		if len(fd.Sources) != 0 && len(fd.Sources) != len(fd.Trajectory)-1 {
406			return fmt.Errorf("%w: frame sources length %d for %d frames", ErrCorrupt, len(fd.Sources), len(fd.Trajectory)-1)
407		}
408		seenIDs := make(map[string]struct{}, len(fd.Landmarks))
409		for _, lm := range fd.Landmarks {
410			if lm.ID == "" {
411				return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
412			}
413			if _, dup := seenIDs[lm.ID]; dup {
414				return fmt.Errorf("%w: duplicate landmark %s", ErrCorrupt, lm.ID)
415			}
416			seenIDs[lm.ID] = struct{}{}
417			if len(lm.Occurrences) == 0 {
418				// 兼容旧布局：平铺字段表示第 1 次出现。
419				if lm.Count < 1 || !isFinite(lm.X) || !isFinite(lm.Y) {
420					return fmt.Errorf("%w: invalid landmark record", ErrCorrupt)
421				}
422				if lm.LegacyCount < 0 || lm.LegacyCount > lm.Count {
423					return fmt.Errorf("%w: invalid legacy count for landmark %s", ErrCorrupt, lm.ID)
424				}
425				if lm.LegacyCount > 0 && (!isFinite(lm.LegacyMX) || !isFinite(lm.LegacyMY)) {
426					return fmt.Errorf("%w: invalid legacy mean for landmark %s", ErrCorrupt, lm.ID)
427				}
428				continue
429			}
430			activeCount := 0
431			for i, oj := range lm.Occurrences {
432				if oj.Number != i+1 || oj.Count < 1 || !isFinite(oj.X) || !isFinite(oj.Y) {
433					return fmt.Errorf("%w: invalid occurrence for landmark %s", ErrCorrupt, lm.ID)
434				}
435				if oj.LegacyCount < 0 || oj.LegacyCount > oj.Count {
436					return fmt.Errorf("%w: invalid legacy count for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
437				}
438				if oj.LegacyCount > 0 && (!isFinite(oj.LegacyMX) || !isFinite(oj.LegacyMY)) {
439					return fmt.Errorf("%w: invalid legacy mean for landmark %s occurrence %d", ErrCorrupt, lm.ID, oj.Number)
440				}
441				if oj.Active {
442					activeCount++
443					if i != len(lm.Occurrences)-1 {
444						return fmt.Errorf("%w: active occurrence %d of landmark %s is not the latest", ErrCorrupt, oj.Number, lm.ID)
445					}
446				} else if oj.InvalidReason == "" {
447					return fmt.Errorf("%w: invalidated occurrence %d of landmark %s lacks reason", ErrCorrupt, oj.Number, lm.ID)
448				}
449				// 出现编号即先后次序，各次出现接纳观测的时间范围必须与之
450				// 相容，否则同一观测可能同时属于两次出现（归属校验只确认能
451				// 归入某一次，不排除同时归入两次）。已失效且首次观测时间
452				// 已知的出现，首次观测不能晚于失效；下一次出现的首次观测
453				// 必须严格晚于上一次的失效时间——首次观测与失效两个端点都
454				// 接纳所在时刻的观测，相等即重叠。第 2 次及以后的出现必定
455				// 在上一次失效之后由本包创建，首次观测时间必须已知；只有
456				// 旧文件的第 1 次出现允许未知（无下界，不把零当作起点）。
457				// 这些检查针对保存的出现记录本身，与重叠范围内当前是否有
458				// 观测无关。
459				if !oj.Active && oj.HasFirstSeen && oj.FirstSeenTime > oj.InvalidTime {
460					return fmt.Errorf("%w: occurrence %d of landmark %s first seen at %d after invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, oj.InvalidTime)
461				}
462				if i > 0 {
463					if !oj.HasFirstSeen {
464						return fmt.Errorf("%w: occurrence %d of landmark %s lacks first seen time", ErrCorrupt, oj.Number, lm.ID)
465					}
466					// 上一次出现必已失效（仍有效且非最后一次已在上面拒绝）。
467					if prev := lm.Occurrences[i-1]; oj.FirstSeenTime <= prev.InvalidTime {
468						return fmt.Errorf("%w: occurrence %d of landmark %s starts at %d before previous invalidation at %d", ErrCorrupt, oj.Number, lm.ID, oj.FirstSeenTime, prev.InvalidTime)
469					}
470				}
471			}
472			if activeCount > 1 {
473				return fmt.Errorf("%w: multiple active occurrences for landmark %s", ErrCorrupt, lm.ID)
474			}
475		}
476		// 观测重放器：各路标历次出现的时间边界（归属规则见 occurrence.go）
477		// 与逐条重建位置的流程（见 replay.go）和回环校正共享同一实现；来源
478		// 帧的归属核对、次数/首次时间统计、位置核对与校正记录路标列表核对
479		// 都经由它进行。旧文件缺省 sources（解码为 nil）时不构建，这些核对
480		// 都不进行。
481		var replay *observationReplay
482		if len(fd.Sources) != 0 {
483			replay = newObservationReplay(fd.Config.MergeDistance)
484			for _, lm := range fd.Landmarks {
485				replay.track(lm.ID, occurrenceWindowsOf(lm))
486			}
487		}
488		// 校验每条带逐帧依据的观测来源：观测路标必须存在，且所在帧时间必须
489		// 落入该路标某一次出现的时间边界（共享规则见 occurrence.go）。旧出现
490		// 已失效不代表其历史观测无效；同一标识两次出现之间（如 200 失效、
491		// 300 再现时的 250 帧）的观测没有归属，按损坏拒绝。null 帧来自缺少
492		// 逐帧依据的旧地图，其观测不在这里（也无法）核验；旧版平铺路标视为
493		// 一次无边界的有效出现，因此旧地图后来追加的来源帧仍按此规则检查。
494		if len(fd.Sources) != 0 {
495			// 归属校验的同时按（路标，出现编号）统计来源观测条数：每条观测
496			// 各算一次，同帧重复观测同一标识不去重，空观测帧不计。null 帧
497			// 缺少逐帧依据，其贡献已固定在出现的旧观测计数中，不在此统计，
498			// 也不能按帧数猜测。同时记录归属各次出现的最早来源观测帧时间，
499			// 供下方首次观测时间核对使用。
500			tallies := make(map[string]map[int]int, len(fd.Landmarks))
501			firstObs := make(map[string]map[int]int64, len(fd.Landmarks))
502			for k, src := range fd.Sources {
503				if src == nil {
504					continue // 旧地图帧：无逐帧依据，不要求补齐归属
505				}
506				t := fd.Trajectory[k+1].Time
507				for _, ob := range src.Observations {
508					num, known := replay.occurrenceOf(ob.ID, t)
509					if !known {
510						return fmt.Errorf("%w: observation of unknown landmark %s at frame time %d", ErrCorrupt, ob.ID, t)
511					}
512					if num == 0 {
513						return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, ob.ID, t)
514					}
515					c := tallies[ob.ID]
516					if c == nil {
517						c = make(map[int]int, 1)
518						tallies[ob.ID] = c
519					}
520					c[num]++
521					f := firstObs[ob.ID]
522					if f == nil {
523						f = make(map[int]int64, 1)
524						firstObs[ob.ID] = f
525					}
526					if cur, ok := f[num]; !ok || t < cur {
527						f[num] = t
528					}
529				}
530			}
531			// 每次出现记录的观测次数必须等于归属该次出现的来源观测条数加上
532			// 该次出现已保存的旧观测贡献：偏多或偏少都是文件损坏。各次出现
533			// 分别核对，不能用另一次出现的观测补足；已失效的旧出现同样核对，
534			// 不因它不再参与区域查询而跳过。回环校正只改位置不改已接受观测
535			// 次数，正常校正后保存的文件仍满足此不变量。
536			for _, lm := range fd.Landmarks {
537				if len(lm.Occurrences) == 0 {
538					// 旧版平铺路标即第 1 次出现。
539					if got := tallies[lm.ID][1] + lm.LegacyCount; got != lm.Count {
540						return fmt.Errorf("%w: landmark %s records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, lm.Count, got)
541					}
542					continue
543				}
544				for _, oj := range lm.Occurrences {
545					if got := tallies[lm.ID][oj.Number] + oj.LegacyCount; got != oj.Count {
546						return fmt.Errorf("%w: landmark %s occurrence %d records %d observations but sources and legacy contributions account for %d", ErrCorrupt, lm.ID, oj.Number, oj.Count, got)
547					}
548				}
549			}
550	
551			// 首次观测时间核对：首次观测时间已知、且全部观测都具有逐帧来源
552			// （无固定旧贡献）的每次出现，记录的首次时间必须准确等于实际归属
553			// 该次出现的最早来源观测帧时间。写早或写晚都是损坏：错误时间即使
554			// 恰好命中某个已保存的帧，只要该帧没有观测这一路标也不能接受；
555			// 错误时间没有对应帧同样拒绝。各次出现分别核对——已失效的旧出现
556			// 与失效后再现的新出现各自依据自己的观测判断，不能互相代替；后续
557			// 帧继续观测或同帧重复观测都不改变首次时间。时间为零或负数是合法
558			// 帧时间，按实际值比较，不把零当作时间未知。旧文件第 1 次出现缺
559			// 少旧观测依据、首次时间未知（HasFirstSeen 为假），或仍含固定旧
560			// 贡献时，其最早观测无从核对，保留旧地图的既有打开规则；但旧路标
561			// 失效后新导入产生的出现依据完整、首次时间已知，不因同一文件存在
562			// 旧历史而跳过核对。回环校正只改位姿与位置，不改观测帧时间，已正
563			// 确保存的校正地图仍满足此不变量。
564			for _, lm := range fd.Landmarks {
565				for _, oj := range lm.Occurrences {
566					if !oj.HasFirstSeen || oj.LegacyCount > 0 {
567						continue
568					}
569					// 次数核对已保证 Count-LegacyCount 条来源观测存在，最早
570					// 帧时间必然已记录；缺失本身即矛盾。
571					first, ok := firstObs[lm.ID][oj.Number]
572					if !ok || first != oj.FirstSeenTime {
573						return fmt.Errorf("%w: landmark %s occurrence %d records first seen time %d but its earliest sourced observation is at frame time %d", ErrCorrupt, lm.ID, oj.Number, oj.FirstSeenTime, first)
574					}
575				}
576			}
577	
578			// 位置核对：次数相符只说明观测“条数”对得上，还必须核对保存的路标
579			// 位置确实是这些观测依据当前保存位姿重放后的等权平均。每条来源观测
580			// 按所在帧当前保存的位姿转换到地图坐标，按帧时间升序、同帧按输入
581			// 次序，归入各自出现分别重放；同帧对同一标识的多条观测各自参与，
582			// 空观测帧不增加贡献。归组、固定旧贡献起点与逐条重建全部经由与
583			// 回环校正共享的重放器（见 replay.go，单条接纳规则见 aggregate.go），
584			// 旧文件固定旧贡献（LegacyCount 次平均）作为聚合起点——不能当成零，
585			// 也不能用缺少依据的帧数代替。回环校正后保存的文件按当前轨迹重放
586			// 即得到当前位置，不要求等于校正记录里的历史快照；各次出现分别核
587			// 对，已失效的出现同样核对。合并距离只是导入/校正时的接纳门槛，不
588			// 是保存位置偏差的容许范围：重放中出现非有限结果或距离冲突，或最
589			// 终平均位置与保存位置不完全一致，都按损坏拒绝。纯旧文件没有
590			// sources、null 旧帧没有依据，均不重放。
591			for _, lm := range fd.Landmarks {
592				if len(lm.Occurrences) == 0 {
593					// 旧版平铺路标即第 1 次出现。
594					replay.seed(lm.ID, 1, lm.LegacyCount, lm.LegacyMX, lm.LegacyMY)
595					continue
596				}
597				for _, oj := range lm.Occurrences {
598					replay.seed(lm.ID, oj.Number, oj.LegacyCount, oj.LegacyMX, oj.LegacyMY)
599				}
600			}
601			frames := make([]replayFrame, 0, len(fd.Sources))
602			for k, src := range fd.Sources {
603				if src == nil {
604					continue // 旧地图帧：无逐帧依据，其贡献固定在旧贡献起点中
605				}
606				pose := fd.Trajectory[k+1]
607				frames = append(frames, replayFrame{time: pose.Time, pose: pose, observations: src.Observations})
608			}
609			if rej := replay.replay(frames); rej != nil {
610				switch rej.reason {
611				case replayNonFinite:
612					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d is non-finite", ErrCorrupt, rej.id, rej.num, rej.time)
613				case replayConflict:
614					return fmt.Errorf("%w: replayed observation of landmark %s occurrence %d at frame time %d violates merge distance", ErrCorrupt, rej.id, rej.num, rej.time)
615				default:
616					// 归属（存在性与时间边界）已在上面校验，不会无法归组。
617					return fmt.Errorf("%w: observation of landmark %s at frame time %d belongs to no occurrence", ErrCorrupt, rej.id, rej.time)
618				}
619			}
620			checkPosition := func(id string, num int, x, y float64) error {
621				a := replay.agg(id, num)
622				// 次数核对已保证 a.count 与记录次数一致（含旧贡献起点），这里只
623				// 核对位置：保存位置必须与按依据重放出的等权平均完全一致。
624				if a.x != x || a.y != y {
625					return fmt.Errorf("%w: landmark %s occurrence %d is saved at (%v,%v) but its observations replay to (%v,%v)", ErrCorrupt, id, num, x, y, a.x, a.y)
626				}
627				return nil
628			}
629			for _, lm := range fd.Landmarks {
630				if len(lm.Occurrences) == 0 {
631					if err := checkPosition(lm.ID, 1, lm.X, lm.Y); err != nil {
632						return err
633					}
634					continue
635				}
636				for _, oj := range lm.Occurrences {
637					if err := checkPosition(lm.ID, oj.Number, oj.X, oj.Y); err != nil {
638						return err
639					}
640				}
641			}
642		}
643		segIDs := make(map[string]struct{}, len(fd.Segments))
644		for _, sg := range fd.Segments {
645			if sg.ID == "" || sg.Hash == "" {
646				return fmt.Errorf("%w: invalid segment record", ErrCorrupt)
647			}
648			if _, dup := segIDs[sg.ID]; dup {
649				return fmt.Errorf("%w: duplicate segment %s", ErrCorrupt, sg.ID)
650			}
651			segIDs[sg.ID] = struct{}{}
652		}
653		corrIDs := make(map[string]struct{}, len(fd.Corrections))
654		for _, cr := range fd.Corrections {
655			if cr.ID == "" || cr.Anchor > cr.EndTime {
656				return fmt.Errorf("%w: invalid correction record", ErrCorrupt)
657			}
658			// 锚点与结束时间必须准确命中已导入帧：trajectory[0] 是初始位姿，
659			// 不是可校正的帧，也不能用相邻帧的时间代替。轨迹时间已在前面
660			// 校验为严格递增，命中即唯一。
661			anchorIdx, endIdx := -1, -1
662			for j := 1; j < len(fd.Trajectory); j++ {
663				if fd.Trajectory[j].Time == cr.Anchor {
664					anchorIdx = j
665				}
666				if fd.Trajectory[j].Time == cr.EndTime {
667					endIdx = j
668				}
669			}
670			if anchorIdx < 0 || endIdx < 0 {
671				return fmt.Errorf("%w: correction %s range does not hit imported frames", ErrCorrupt, cr.ID)
672			}
673			// 记录必须恰好覆盖 [anchor, end] 内的每一帧：位姿条目数量等于
674			// 范围内帧数，按轨迹时间次序一一对应，且同一份前后位姿的时间
675			// 相同并就是对应帧的时间。缺失、重复、错序、额外加入范围外的
676			// 帧，或把前后时间写成两个不同帧，都使记录不能完整描述声明的
677			// 范围，按损坏拒绝。这里只核对覆盖的帧及时间：快照中的位置、
678			// 朝向和方差是提交时的历史值，不要求等于当前轨迹（后来对相同
679			// 范围再校正、或之后导入新帧，都不影响既有记录的合法性）。
680			if len(cr.Poses) != endIdx-anchorIdx+1 {
681				return fmt.Errorf("%w: correction %s does not cover every frame in its range", ErrCorrupt, cr.ID)
682			}
683			for i, pc := range cr.Poses {
684				ft := fd.Trajectory[anchorIdx+i].Time
685				if pc.Before.Time != ft || pc.After.Time != ft {
686					return fmt.Errorf("%w: correction %s pose entry %d does not match frame time %d", ErrCorrupt, cr.ID, i, ft)
687				}
688				if !finitePose(pc.Before) || !finitePose(pc.After) {
689					return fmt.Errorf("%w: correction %s has non-finite pose", ErrCorrupt, cr.ID)
690				}
691			}
692			// 以下两项核对都只针对范围内逐帧依据完整的校正：范围内任一来源
693			// 帧为 null 旧帧时保留旧文件的既有打开规则，不推测运动方差、也
694			// 不把未知贡献当成零；纯旧文件缺省 sources（长度为 0，重放器不构
695			// 建）时所有记录都不核对。同一文件的其余依据完整的记录不受含旧帧
696			// 记录影响，仍逐一核对。
697			fullyBased := len(fd.Sources) != 0
698			if fullyBased {
699				for k := anchorIdx - 1; k <= endIdx-1; k++ {
700					if fd.Sources[k] == nil {
701						fullyBased = false
702						break
703					}
704				}
705			}
706			if fullyBased {
707				// 校正后方差核对：锚点帧的校正后方差必须等于该次提交的目标
708				// 方差；其后每帧在目标方差上，按时间顺序累加锚点之后至该帧
709				// 的原运动方差。锚点自身进入该帧的运动方差不再加一次，也不
710				// 能以校正前方差作为起点；累计范围以本记录自己的锚点与结束
711				// 时间为准，后来对重叠范围的再校正与之后追加的帧都不属于本
712				// 记录。目标方差或参与累计的运动方差为负/非有限、累计结果非
713				// 有限，或与保存的校正后方差不完全一致，都按损坏拒绝整份文
714				// 件——每一帧逐一核对，不能只凭锚点与末帧正确就接受中间错误
715				// 的记录；目标方差与运动方差全为零的合法校正同样逐帧通过。
716				accum := cr.Target.Variance
717				if !isFinite(accum) || accum < 0 {
718					return fmt.Errorf("%w: correction %s target variance is negative or non-finite", ErrCorrupt, cr.ID)
719				}
720				for i, pc := range cr.Poses {
721					if i > 0 {
722						// 记录内第 i 帧位于轨迹下标 anchorIdx+i；进入它的运
723						// 动方差在来源 sources[anchorIdx+i-1]（i=1 即锚点之
724						// 后第一帧），锚点自身的来源 sources[anchorIdx-1] 不
725						// 参与累计。
726						mv := fd.Sources[anchorIdx+i-1].MoveVariance
727						if !isFinite(mv) || mv < 0 {
728							return fmt.Errorf("%w: correction %s accumulates negative or non-finite motion variance at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
729						}
730						accum += mv
731						if !isFinite(accum) {
732							return fmt.Errorf("%w: correction %s corrected variance accumulates to non-finite value at frame time %d", ErrCorrupt, cr.ID, pc.After.Time)
733						}
734					}
735					if pc.After.Variance != accum {
736						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected variance %v but target variance %v and the motion variances after the anchor accumulate to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Variance, cr.Target.Variance, accum)
737					}
738				}
739				// 几何核对：整条记录必须描述同一次平移和旋转。只核对该记录
740				// 自身保存的校正前后值与目标，不要求历史快照等于当前轨迹——
741				// 后来对重叠范围再校正、或在结束时间之后追加轨迹，都不改写旧
742				// 记录，也不能使原本合法的旧记录被拒绝。重定位规则与 Correct
743				// 提交时共享同一实现（poseShift，见 correction.go）：旋转角、
744				// 余弦正弦与期望位姿的运算次序完全一致，本包写出的合法记录重
745				// 算出的期望值与保存值逐位相同；这里另按容差接纳浮点重算误
746				// 差。锚点的校正后位置必须是目标位置、朝向必须是目标朝向归一
747				// 到 [-π,π) 的结果；其余帧必须与锚点一起做同一次刚体重定
748				// 位：保留校正前相对锚点的位置关系与朝向差。每一帧都逐一核
749				// 对——只有锚点与末帧正确而中间一帧位置偏离或单独转向，同样
750				// 按损坏拒绝；范围只有锚点一帧时本核对即只针对该帧。坐标容差
751				// 为 1e-9 乘以 1、期望值绝对值、保存值绝对值三者的最大值；
752				// 朝向按最短角度差比较，容差 1e-9 弧度。容差与路标合并距离无
753				// 关：合并距离只是导入/校正时的观测接纳门槛，不能用来放过记
754				// 录内部的几何矛盾。目标位置/朝向与锚点校正前完全相同（角度
755				// 等价）时是恒等（只调方差）校正，期望几何直接取校正前值，与
756				// Correct 的同一分支保持一致：横跨 ±1e308 的轨迹上“相对锚
757				// 点偏移”会溢出，不能因此把合法的恒等校正误判为损坏。
758				anchorBefore := cr.Poses[0].Before
759				shift := newPoseShift(cr.Target, anchorBefore)
760				for i, pc := range cr.Poses {
761					var wantX, wantY, wantHeading float64
762					if i == 0 {
763						wantX, wantY, wantHeading = shift.x, shift.y, shift.heading
764					} else {
765						wantX, wantY, wantHeading = shift.apply(pc.Before)
766					}
767					if !coordClose(pc.After.X, wantX) {
768						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected x %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.X, wantX)
769					}
770					if !coordClose(pc.After.Y, wantY) {
771						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected y %v but the record's target and pre-correction poses rigidly move it to %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Y, wantY)
772					}
773					if !angleClose(pc.After.Heading, wantHeading) {
774						return fmt.Errorf("%w: correction %s pose at frame time %d has corrected heading %v but the record's rotation makes it %v", ErrCorrupt, cr.ID, pc.After.Time, pc.After.Heading, wantHeading)
775					}
776				}
777			}
778			for _, lc := range cr.Landmarks {
779				if lc.ID == "" {
780					return fmt.Errorf("%w: correction %s has empty landmark id", ErrCorrupt, cr.ID)
781				}
782				if lc.Occurrence < 0 || !isFinite(lc.Before.X) || !isFinite(lc.Before.Y) ||
783					!isFinite(lc.After.X) || !isFinite(lc.After.Y) ||
784					lc.Before.Count < 1 || lc.After.Count < 1 {
785					return fmt.Errorf("%w: correction %s has invalid landmark change", ErrCorrupt, cr.ID)
786				}
787			}
788			// 路标列表必须恰好描述记录范围（锚点帧到结束帧，两端包含；之后
789			// 追加的帧不属于范围）内逐帧观测实际涉及的路标出现：范围内被观测
790			// 到的每个（路标，出现编号）必须恰好有一条前后记录，同一次出现被
791			// 多帧或同帧多条观测涉及也只记一条；少记、多记、重复、或把出现
792			// 编号改指该范围没有涉及的另一出现，都按损坏拒绝整份文件，而不是
793			// 只看条目里的坐标与次数是否合法。归组沿用与回环校正相同的时间边
794			// 界规则（重放器，见 replay.go）：同一标识失效后再现属于不同出现，
795			// 即使位置相同也分别对应；已失效的旧出现只要范围内（含失效时刻）
796			// 有它的观测就必须在列表中，不因当前区域查询不再返回它而被排除；
797			// 范围外帧（如记录之后才再现的新出现）的观测不计入。范围内没有
798			// 任何路标观测时列表必须为空，非空即损坏。仅对范围内逐帧依据完整
799			// 的校正做此核对：范围内含 null 旧帧的校正缺少逐帧依据，保留旧地
800			// 图的既有打开规则，不凭推测要求补造观测。
801			if replay != nil && fullyBased {
802				rangeFrames := make([]replayFrame, 0, endIdx-anchorIdx+1)
803				for j := anchorIdx; j <= endIdx; j++ {
804					rangeFrames = append(rangeFrames, replayFrame{time: fd.Trajectory[j].Time, observations: fd.Sources[j-1].Observations})
805				}
806				want := replay.observed(rangeFrames)
807				got := make(map[occurrenceKey]struct{}, len(cr.Landmarks))
808				for _, lc := range cr.Landmarks {
809					num := lc.Occurrence
810					if num == 0 {
811						num = 1 // 更早版本写出的校正记录不带编号，按第 1 次出现解释
812					}
813					if num < 1 || num > replay.occurrences(lc.ID) {
814						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d not touched by its range", ErrCorrupt, cr.ID, lc.ID, num)
815					}
816					key := occurrenceKey{id: lc.ID, num: num}
817					if _, dup := got[key]; dup {
818						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d more than once", ErrCorrupt, cr.ID, lc.ID, num)
819					}
820					got[key] = struct{}{}
821				}
822				for key := range want {
823					if _, ok := got[key]; !ok {
824						return fmt.Errorf("%w: correction %s misses landmark %s occurrence %d observed in its range", ErrCorrupt, cr.ID, key.id, key.num)
825					}
826				}
827				for key := range got {
828					if _, ok := want[key]; !ok {
829						return fmt.Errorf("%w: correction %s lists landmark %s occurrence %d with no observation in its range", ErrCorrupt, cr.ID, key.id, key.num)
830					}
831				}
832			}
833			if _, dup := corrIDs[cr.ID]; dup {
834				return fmt.Errorf("%w: duplicate correction %s", ErrCorrupt, cr.ID)
835			}
836			corrIDs[cr.ID] = struct{}{}
837		}
838		// 路标记录按标识索引，供失效记录与出现历史的交叉核对使用。
839		lmByID := make(map[string]*landmarkJSON, len(fd.Landmarks))
840		for i := range fd.Landmarks {
841			lmByID[fd.Landmarks[i].ID] = &fd.Landmarks[i]
842		}
843		invalIDs := make(map[string]struct{}, len(fd.Invalidations))
844		// invalTriples 记录每条失效操作实际引用的（操作标识，路标，出现编号）
845		// 三元组，供反向核对：每个已失效出现都必须是某条操作记录里的实际条目。
846		type invalTriple struct {
847			op  string
848			lm  string
849			num int
850		}
851		invalTriples := make(map[invalTriple]struct{}, len(fd.Invalidations))
852		for _, iv := range fd.Invalidations {
853			if iv.ID == "" || iv.Reason == "" || iv.Hash == "" || len(iv.Landmarks) == 0 {
854				return fmt.Errorf("%w: invalid invalidation record", ErrCorrupt)
855			}
856			if _, dup := invalIDs[iv.ID]; dup {
857				return fmt.Errorf("%w: duplicate invalidation %s", ErrCorrupt, iv.ID)
858			}
859			invalIDs[iv.ID] = struct{}{}
860			lmSeen := make(map[string]struct{}, len(iv.Landmarks))
861			for _, l := range iv.Landmarks {
862				if l.ID == "" || l.Occurrence < 1 {
863					return fmt.Errorf("%w: invalid invalidation landmark entry", ErrCorrupt)
864				}
865				if _, dup := lmSeen[l.ID]; dup {
866					return fmt.Errorf("%w: invalidation %s lists %s twice", ErrCorrupt, iv.ID, l.ID)
867				}
868				lmSeen[l.ID] = struct{}{}
869			}
870			// 交叉核对：成功失效结果里的每个（路标标识，出现编号）必须准确
871			// 指向该路标历史中同编号的那次出现，不能改指同一路标的其他出现，
872			// 也不能因为路标后来再次出现就把旧结果指向最新记录。被指出现必须
873			// 已经失效，且其上记录的失效操作标识、失效时间、失效原因都与这条
874			// 操作记录一致——时间与原因各自再合理也不够，实际由另一条操作撤下
875			// 时不能仅凭相同时间/原因认可。旧版平铺路标视为第 1 次有效出现，
876			// 不可能被失效记录引用（引用即损坏）。一条操作同时撤下多个路标时，
877			// 任意一个条目不满足对应关系都拒绝打开整个文件。
878			for _, l := range iv.Landmarks {
879				lm := lmByID[l.ID]
880				if lm == nil {
881					return fmt.Errorf("%w: invalidation %s result points to unknown landmark %s", ErrCorrupt, iv.ID, l.ID)
882				}
883				if len(lm.Occurrences) == 0 {
884					return fmt.Errorf("%w: invalidation %s result points to flat legacy landmark %s which has no invalidated occurrence", ErrCorrupt, iv.ID, l.ID)
885				}
886				if l.Occurrence > len(lm.Occurrences) {
887					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which does not exist", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
888				}
889				// 出现编号连续性已在上方路标校验中强制，该下标处编号即 l.Occurrence。
890				oj := lm.Occurrences[l.Occurrence-1]
891				if oj.Active {
892					return fmt.Errorf("%w: invalidation %s result points to landmark %s occurrence %d which is still active", ErrCorrupt, iv.ID, l.ID, l.Occurrence)
893				}
894				if oj.InvalidOpID != iv.ID || oj.InvalidTime != iv.Time || oj.InvalidReason != iv.Reason {
895					return fmt.Errorf("%w: invalidation %s result for landmark %s occurrence %d does not match its saved invalidation (op %q, time %d, reason %q)", ErrCorrupt, iv.ID, l.ID, l.Occurrence, oj.InvalidOpID, oj.InvalidTime, oj.InvalidReason)
896				}
897				invalTriples[invalTriple{op: iv.ID, lm: l.ID, num: l.Occurrence}] = struct{}{}
898			}
899		}
900		// 反向核对：每个已失效出现都必须能在失效操作序列中找到引用同一（操作，
901		// 路标，出现编号）三元组的条目。正向核对已保证被引用出现的失效时间与
902		// 原因和引用方一致；此处堵住另一方向的矛盾：出现凭空携带失效信息、
903		// 声称撤下它的操作记录实际指向另一次出现，或两次出现声称被同一操作
904		// 撤下（一次操作对同一路标只会撤下当时唯一的有效出现）。旧地图没有
905		// 失效操作时，平铺路标视为有效、不携带失效信息，不会触发；旧地图后来
906		// 产生的失效操作同样在上述核对之列，不要求补齐原本缺失的逐帧观测。
907		for _, lm := range fd.Landmarks {
908			for _, oj := range lm.Occurrences {
909				if oj.Active {
910					continue
911				}
912				if _, ok := invalTriples[invalTriple{op: oj.InvalidOpID, lm: lm.ID, num: oj.Number}]; !ok {
913					return fmt.Errorf("%w: landmark %s occurrence %d is marked invalidated by operation %q which does not record that invalidation", ErrCorrupt, lm.ID, oj.Number, oj.InvalidOpID)
914				}
915			}
916		}
917		return nil
918	}
919	
920	func finitePose(p Pose) bool {
921		return isFinite(p.X) && isFinite(p.Y) && isFinite(p.Heading) && isFinite(p.Variance)
922	}
923	
924	// geomTol 是打开时核对校正记录几何一致性的相对容差（另含 1 的绝对项）。
925	const geomTol = 1e-9
926	
927	// coordClose 判断保存坐标 got 是否在容许误差内等于期望 want：误差不得
928	// 超过 geomTol 乘以 1、|want|、|got| 三者中的最大值。参与比较的值都已
929	// 校验为有限，差值必有限，NaN 不会混入并被误当相等。
930	func coordClose(got, want float64) bool {
931		scale := math.Max(1, math.Max(math.Abs(want), math.Abs(got)))
932		return math.Abs(got-want) <= geomTol*scale
933	}
934	
935	// angleClose 按最短角度差判断两个角度是否相等，容差 geomTol 弧度。两个
936	// 角度都已校验为有限；差值经归一化到 [-π,π) 即最短角度差，正确处理
937	// ±π 附近跨边界但物理方向相同的情形。
938	func angleClose(got, want float64) bool {
939		return math.Abs(normalizeAngle(got-want)) <= geomTol
940	}
941	
942	// canonicalCorrectionHash 计算一次校正请求（锚点时间 + 目标位姿）的
943	// 确定性指纹，用于同标识重复提交判定。直接按 IEEE-754 位编码。
944	func canonicalCorrectionHash(anchor int64, tgt CorrectionTarget) string {
945		h := sha256.New()
946		var b [8]byte
947		binary.BigEndian.PutUint64(b[:], uint64(anchor))
948		h.Write(b[:])
949		for _, v := range []float64{tgt.X, tgt.Y, tgt.Heading, tgt.Variance} {
950			binary.BigEndian.PutUint64(b[:], math.Float64bits(v))
951			h.Write(b[:])
952		}
953		return fmt.Sprintf("%x", h.Sum(nil))
954	}
955	
956	// saveExclusive 创建新文件，目标已存在即失败（O_EXCL）。
957	func (m *Map) saveExclusive() error {
958		data, err := encodeFile(m.state)
959		if err != nil {
960			return err
961		}
962		f, err := os.OpenFile(m.path, os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0o644)
963		if err != nil {
964			return err
965		}
966		return writeAndClose(f, data, m.path)
967	}
968	
969	// saveReplace 用同目录临时文件 + rename 原子替换现有文件。
970	func (m *Map) saveReplace() (err error) {
971		data, err := encodeFile(m.state)
972		if err != nil {
973			return err
974		}
975		dir, base := filepath.Split(m.path)
976		if dir == "" {
977			dir = "."
978		}
979		f, err := os.CreateTemp(dir, base+".tmp-*")
980		if err != nil {
981			return err
982		}
983		tmpName := f.Name()
984		// 任何失败路径都尽力清理临时文件。
985		defer func() {
986			if err != nil {
987				_ = os.Remove(tmpName)
988			}
989		}()
990		if err = writeAndClose(f, data, tmpName); err != nil {
991			return err
992		}
993		if err = os.Rename(tmpName, m.path); err != nil {
994			return err
995		}
996		return nil
997	}
998	
999	func writeAndClose(f *os.File, data []byte, name string) (err error) {
1000		defer func() {
1001			if cerr := f.Close(); err == nil {
1002				err = cerr
1003			}
1004		}()
1005		if _, err = f.Write(data); err != nil {
1006			return err
1007		}
1008		if err = f.Sync(); err != nil {
1009			return err
1010		}
1011		return nil
1012	}
1013	
1014	// canonicalHash 计算一批帧的确定性指纹，用于重复导入判定。直接按
1015	// IEEE-754 位编码，NaN/Inf 也有稳定表示，不依赖 JSON 对其不支持的问题。
1016	func canonicalHash(frames []Frame) string {
1017		h := sha256.New()
1018		var lenBuf [4]byte
1019		var numBuf [8]byte
1020		putU32 := func(v uint32) {
1021			binary.BigEndian.PutUint32(lenBuf[:], v)
1022			h.Write(lenBuf[:])
1023		}
1024		putU64 := func(v uint64) {
1025			binary.BigEndian.PutUint64(numBuf[:], v)
1026			h.Write(numBuf[:])
1027		}
1028		putStr := func(s string) {
1029			putU32(uint32(len(s)))
1030			h.Write([]byte(s))
1031		}
1032	
1033		putU32(uint32(len(frames)))
1034		for _, fr := range frames {
1035			putU64(uint64(fr.Time))
1036			putU64(math.Float64bits(fr.DX))
1037			putU64(math.Float64bits(fr.DY))
1038			putU64(math.Float64bits(fr.DHeading))
1039			putU64(math.Float64bits(fr.MoveVariance))
1040			putU32(uint32(len(fr.Observations)))
1041			for _, ob := range fr.Observations {
1042				putStr(ob.ID)
1043				putU64(math.Float64bits(ob.X))
1044				putU64(math.Float64bits(ob.Y))
1045			}
1046		}
1047		return fmt.Sprintf("%x", h.Sum(nil))
1048	}
1049

